// FlowmaidPromo — composition root. 1080×1350 @ 30 fps, SILENT master.
// Renders one Sequence per shot (one file per shot in ./shots), the seams derived from
// TRANSITIONS (accent-line wipe / mode-switch circle / opening header handoff), the
// opening overlay, and the caption layer driven by CAPTIONS. Owned by the scaffold:
// shot packages do not edit this file.
import React from 'react';
import { AbsoluteFill, Freeze, Sequence, useCurrentFrame } from 'remotion';
import { ModeLayer } from './Chrome';
import { VoCaption } from './lib/Caption';
import { Guides } from './lib/Placeholder';
import {
  CAPTIONS, HEADER_HANDOFF, SHOTS, SHOT_ORDER, TOTAL, VO_LINES, chromeWordmarkVisibleAt, headerProgressAt, knobAt,
  transitionInto, transitionOutOf, type ShotId,
} from './timeline';
import { FOOTER_H, HEADER, HEADER_H, PAPER, coverRadius, ease, loadFlowmaidFonts, palette, prog } from './tokens';
import { OpenOverlay, OpenShot } from './shots/Open';
import { RenderShot } from './shots/Render';
import { SpeedShot } from './shots/Speed';
import { TypesShot } from './shots/Types';
import { BrowserShot } from './shots/Browser';
import { FlowcliShot } from './shots/Flowcli';
import { DbxShot } from './shots/Dbx';
import { OutroShot } from './shots/Outro';

loadFlowmaidFonts();

export const FLOWMAID_TOTAL = TOTAL;

const SHOT_COMPONENTS: Record<ShotId, React.FC> = {
  open: OpenShot, render: RenderShot, speed: SpeedShot, types: TypesShot,
  browser: BrowserShot, flowcli: FlowcliShot, dbx: DbxShot, outro: OutroShot,
};

/** clip-path revealing shot `id` at global frame `g` (undefined = fully visible). */
const revealClip = (id: ShotId, g: number): string | undefined => {
  const t = transitionInto(id);
  if (!t || t.frames === 0 || g >= t.at + t.frames) return undefined;
  const p = ease.inout(prog(g, t.at, t.frames));
  if (t.kind === 'wipe') return `inset(0 ${((1 - p) * 100).toFixed(3)}% 0 0)`;
  const c = t.toMode === 'ink' ? HEADER.toggle.inkCenter : HEADER.toggle.paperCenter;
  return `circle(${(p * coverRadius(c.x, c.y)).toFixed(2)}px at ${c.x}px ${c.y}px)`;
};

/** One shot inside its mode chrome. `g` = global frame (chrome props come from the timeline). */
const ShotLayer: React.FC<{ id: ShotId; g: number; clip?: string; guides: boolean }> = ({ id, g, clip, guides }) => {
  const s = SHOTS[id];
  const Comp = SHOT_COMPONENTS[id];
  return (
    <ModeLayer
      mode={s.mode}
      knob={knobAt(g, s.mode)}
      headerProgress={id === 'open' ? headerProgressAt(g) : 1}
      wordmarkVisible={id === 'open' ? chromeWordmarkVisibleAt(g) : true}
      clipPath={clip}
    >
      <Comp />
      {guides ? <Guides color={palette(s.mode).accent} /> : null}
    </ModeLayer>
  );
};

/** accent line riding the wipe edge (canvas height only), fx.html. */
const WipeLine: React.FC<{ g: number }> = ({ g }) => {
  for (const id of SHOT_ORDER) {
    const t = transitionInto(id);
    if (!t || t.kind !== 'wipe') continue;
    if (g >= t.at && g < t.at + t.frames) {
      const p = ease.inout(prog(g, t.at, t.frames));
      return (
        <div
          style={{
            position: 'absolute', top: HEADER_H, bottom: FOOTER_H, width: 2, left: p * 1080 - 1,
            background: palette(t.toMode).accent,
          }}
        />
      );
    }
  }
  return null;
};

/** Thumbnail / cover variant (props {cover: true}, rendered as a still of the last frame): the
 * film's final lockup with the VO1 line (the product statement) in the caption box instead of the
 * fading CTA caption. Same components, same tokens; nothing else changes. */
const CoverCaption: React.FC = () => (
  <Sequence from={TOTAL - 30} layout="none" name="cover caption">
    <VoCaption text={VO_LINES[0].text} mode="paper" duration={10000} />
  </Sequence>
);

export const FlowmaidPromo: React.FC<{ guides?: boolean; cover?: boolean }> = ({ guides = false, cover = false }) => {
  const g = useCurrentFrame();
  return (
    <AbsoluteFill style={{ background: PAPER.bg }}>
      {SHOT_ORDER.map((id) => {
        const s = SHOTS[id];
        const out = transitionOutOf(id);
        return (
          <React.Fragment key={id}>
            <Sequence from={s.from} durationInFrames={s.duration} name={`${s.index + 1} ${id}`}>
              <ShotLayer id={id} g={g} clip={revealClip(id, g)} guides={guides} />
            </Sequence>
            {/* outgoing shot held on its last frame underneath the next seam's reveal */}
            {out && out.frames > 0 ? (
              <Sequence from={s.end} durationInFrames={out.frames} name={`${id} (held)`}>
                <Freeze frame={s.duration - 1}>
                  <ShotLayer id={id} g={g} guides={guides} />
                </Freeze>
              </Sequence>
            ) : null}
          </React.Fragment>
        );
      })}

      <WipeLine g={g} />

      {/* opening overlay: the big wordmark docking into the header (frame coords) */}
      <Sequence from={SHOTS.open.from} durationInFrames={HEADER_HANDOFF.to - SHOTS.open.from} name="open overlay">
        <AbsoluteFill>
          <OpenOverlay />
        </AbsoluteFill>
      </Sequence>

      {/* burned-in voice-over captions (one table: CAPTIONS, derived from SHOTS) */}
      {cover ? <CoverCaption /> : null}
      {cover ? null : CAPTIONS.map((c) => (
        <Sequence key={c.id} from={c.from} durationInFrames={c.to - c.from} name={`caption ${c.id}`} layout="none">
          <VoCaption text={c.text} mode={c.mode} duration={c.to - c.from} />
        </Sequence>
      ))}
    </AbsoluteFill>
  );
};
